-- SCOTT loader. Le source n'est pas lisible ici.
local KEY = "ScttN3onX7"
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local PAYLOAD = ""

local function dec(data)
    local map = {}
    for i = 1, #B64 do
        map[B64:sub(i, i)] = i - 1
    end
    data = data:gsub("%s", "")
    local out = {}
    local i = 1
    while i <= #data do
        local c1 = map[data:sub(i, i)] or 0
        local c2 = map[data:sub(i + 1, i + 1)] or 0
        local a = data:sub(i + 2, i + 2)
        local b = data:sub(i + 3, i + 3)
        local c3 = a ~= "=" and map[a] or 0
        local c4 = b ~= "=" and map[b] or 0
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        out[#out + 1] = string.char(math.floor(n / 65536) % 256)
        if a ~= "=" then
            out[#out + 1] = string.char(math.floor(n / 256) % 256)
        end
        if b ~= "=" then
            out[#out + 1] = string.char(n % 256)
        end
        i = i + 4
    end
    local raw = table.concat(out)
    local res = {}
    for j = 1, #raw do
        local k = KEY:byte(((j - 1) % #KEY) + 1)
        res[j] = string.char(bit32.bxor(raw:byte(j), k))
    end
    return table.concat(res)
end


local API_URL = "https://script.google.com/macros/s/AKfycbwAMjtFtCAF0F80-H4YqkPdBdZdPZjGvK3ocr57PCRzXLguV3v49W0z8OQykBE_IA8o4Q/exec"
local SAVE = "ScottKey.txt"

local function trim(s)
    return (tostring(s or "")):gsub("^%s+", ""):gsub("%s+$", ""):gsub("\r", "")
end

local function myId()
    return tostring(game:GetService("Players").LocalPlayer.UserId)
end

local function grab(url)
    local function clean(s)
        if type(s) ~= "string" then
            return nil
        end
        s = trim(s)
        if s == "" or s:find("<html", 1, true) or s:find("<!DOCTYPE", 1, true) then
            return nil
        end
        return s
    end
    local ok, body = pcall(function()
        return game:HttpGet(url)
    end)
    body = ok and clean(body)
    if body then
        return body
    end
    local req = request or http_request or (syn and syn.request)
    if type(req) == "function" then
        local ok2, res = pcall(req, { Url = url, Method = "GET" })
        if ok2 and type(res) == "table" then
            body = clean(res.Body)
            if body then
                return body
            end
            local headers = res.Headers or res.headers or {}
            local loc = headers.Location or headers.location
            if type(loc) == "string" and loc ~= "" then
                local ok3, body2 = pcall(function()
                    return game:HttpGet(loc)
                end)
                body2 = ok3 and clean(body2)
                if body2 then
                    return body2
                end
            end
        end
    end
    if not ok then
        error(tostring(body))
    end
    return ""
end

local function keyOk(pass)
    local url = API_URL .. "?key=" .. game:GetService("HttpService"):UrlEncode(pass) .. "&id=" .. game:GetService("HttpService"):UrlEncode(myId())
    local last = "SERVEUR"
    for _ = 1, 3 do
        local ok, body = pcall(grab, url)
        if ok and type(body) == "string" then
            body = trim(body)
            if body == "OK" or body:find("OK") then
                return true, "OK"
            end
            if body:find("USED") then
                return false, "USED"
            end
            if body:find("OFF") then
                return false, "OFF"
            end
            if body:find("NO") then
                return false, "NO"
            end
            if body ~= "" then
                last = body:sub(1, 24)
            end
        else
            last = "SERVEUR"
        end
        task.wait(0.6)
    end
    return false, last
end

local function askKey()
    local Players = game:GetService("Players")
    local lp = Players.LocalPlayer
    local parent = nil
    if type(gethui) == "function" then
        local ok, h = pcall(gethui)
        if ok and typeof(h) == "Instance" then
            parent = h
        end
    end
    if not parent then
        local ok, cg = pcall(function()
            return game:GetService("CoreGui")
        end)
        if ok then
            parent = cg
        end
    end
    if not parent then
        parent = lp:WaitForChild("PlayerGui")
    end
    local old = parent:FindFirstChild("ScottKeyGate")
    if old then
        old:Destroy()
    end
    local gui = Instance.new("ScreenGui")
    gui.Name = "ScottKeyGate"
    gui.ResetOnSpawn = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder = 100000
    gui.Parent = parent
    local box = Instance.new("Frame")
    box.Size = UDim2.fromOffset(340, 190)
    box.Position = UDim2.new(0.5, -170, 0.5, -95)
    box.BackgroundColor3 = Color3.fromRGB(8, 12, 9)
    box.Parent = gui
    Instance.new("UICorner", box).CornerRadius = UDim.new(0, 10)
    local title = Instance.new("TextLabel")
    title.BackgroundTransparency = 1
    title.Size = UDim2.new(1, -16, 0, 52)
    title.Position = UDim2.fromOffset(8, 8)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 15
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextColor3 = Color3.fromRGB(225, 255, 230)
    title.Text = "SCOTT\nID " .. myId()
    title.Parent = box
    local input = Instance.new("TextBox")
    input.Size = UDim2.new(1, -16, 0, 36)
    input.Position = UDim2.fromOffset(8, 70)
    input.BackgroundColor3 = Color3.fromRGB(13, 18, 14)
    input.TextColor3 = Color3.fromRGB(225, 255, 230)
    input.PlaceholderText = "ta clé"
    input.PlaceholderColor3 = Color3.fromRGB(120, 140, 125)
    input.Font = Enum.Font.GothamMedium
    input.TextSize = 14
    input.ClearTextOnFocus = false
    input.Text = ""
    input.Parent = box
    Instance.new("UICorner", input).CornerRadius = UDim.new(0, 8)
    local go = Instance.new("TextButton")
    go.Size = UDim2.new(1, -16, 0, 36)
    go.Position = UDim2.fromOffset(8, 122)
    go.BackgroundColor3 = Color3.fromRGB(0, 200, 70)
    go.TextColor3 = Color3.fromRGB(8, 12, 9)
    go.Font = Enum.Font.GothamBold
    go.TextSize = 14
    go.Text = "Valider"
    go.Parent = box
    Instance.new("UICorner", go).CornerRadius = UDim.new(0, 8)
    local done = nil
    go.MouseButton1Click:Connect(function()
        local pass = trim(input.Text)
        if pass == "" then
            title.Text = "Clé vide"
            return
        end
        title.Text = "Vérification..."
        local okCheck, reason = keyOk(pass)
        if okCheck then
            done = pass
            gui:Destroy()
        elseif reason == "USED" then
            title.Text = "Déjà prise\npar un autre compte"
        else
            title.Text = "Refus: " .. tostring(reason)
        end
    end)
    while not done do
        task.wait(0.1)
    end
    return done
end

local pass = ""
if type(isfile) == "function" and isfile(SAVE) and type(readfile) == "function" then
    local ok, saved = pcall(readfile, SAVE)
    if ok then
        pass = trim(saved)
    end
end
if pass == "" or not keyOk(pass) then
    pass = askKey()
end
if type(writefile) == "function" then
    pcall(writefile, SAVE, pass)
end

local src = dec(PAYLOAD)
local fn, err = loadstring(src)
if not fn then
    error("[SCOTT] " .. tostring(err))
end
fn()
